const event = $input.first().json;
const msg = event.message || {};
const fromUser = msg.from || {};
if (fromUser.is_bot) {
  return [];
}
let text = msg.text ? String(msg.text).trim() : '';
if (!text && msg.caption) text = String(msg.caption).trim();
const hasPhoto = Array.isArray(msg.photo) && msg.photo.length > 0;
if (!text && !hasPhoto) {
  return [];
}
const chat = msg.chat || {};
const chatId = String(chat.id || '');
const chatKind = (chat.type === 'group' || chat.type === 'supergroup') ? 'group' : 'dm';
const help = [
  'Academy bot. I host this student room — not the company ops desk.',
  'Talk about your course. No prefix needed. /cm or /community to be sure.',
  'I stay quiet when you are just chatting.',
  'Login, payment, or a missing certificate: I pass that to a human.',
  'Books, legal, HR, and info@ drafts are the ops Telegram bot, not me.'
].join('\n');
if (/^\/(start|help)(?:@\w+)?\b/i.test(text)) {
  return [{ json: { skip_llm: true, chat_id: chatId, text: help } }];
}
if (/^\/(approve|kill|accounts|ops|legal|hr|growth|crm|validate)(?:@\w+)?\b/i.test(text)) {
  return [{ json: { skip_llm: true, chat_id: chatId, text: 'This is the Academy bot. I cannot do books, legal, HR, or send email. Use the ops Telegram bot for that. Here, talk about your course — or /cm.' } }];
}
text = text.replace(/^(?:\/community|\/cm)(?:@\w+)?\b\s*/i, '').trim();
if (hasPhoto && !text) {
  text = 'A student sent a photo. If it is a study screenshot, help from the catalog. If it looks like a receipt or payment, escalate to a human. Do not invent amounts or treat it as bookkeeping.';
} else if (!text) {
  text = 'Welcome this person and ask which course and lesson they are on.';
}
return [{
  json: {
    skip_llm: false,
    department: 'community',
    task_description: text,
    context_data: {
      channel: 'telegram',
      chat_kind: chatKind,
      department: 'community',
      chat_id: chatId,
      telegram_chat_id: chatId,
      from: String(fromUser.id || ''),
      username: fromUser.username || ''
    }
  }
}];

const prep = $('Prepare task').first().json;
const ctx = Object.assign({}, prep.context_data || {});
try {
  const m = $('Fetch mandate').first().json || {};
  if (m.found && m.mandate) ctx.mandate = m.mandate;
} catch (e) {}
return [{ json: { ...prep, context_data: ctx } }];

const worker = $input.first().json || {};
const ctx = $('Attach mandate').item.json.context_data;
const sd = worker.structured_data || {};
if (sd.speak === false || sd.speak === 'false' || !String(worker.output_text || '').trim()) {
  return [];
}
let text = String(worker.output_text || 'Sorry, I could not complete that.');
text = text.replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();
if (text.length > 4000) {
  text = text.slice(0, 3990) + '\u2026';
}
return [{ json: { chat_id: ctx.chat_id, text } }];
